public function createRole(AppDisplaySettings $settings, IconRegistry $iconRegistry, AdminActivity $adminActivity): void
    {
        if (! Auth::user()?->hasRole('Super-Admin')) {
            Flux::toast(
                // i18n-native: __('admin.roles.messages.not_allowed.heading')
                heading: __('admin.roles.messages.not_allowed.heading'),
                // i18n-native: __('admin.roles.messages.not_allowed.only_super_admins_may_create_roles')
                text: __('admin.roles.messages.not_allowed.only_super_admins_may_create_roles'),
                variant: 'danger',
                duration: 4000,
            );

            return;
        }

        $this->validate([
            'creatingRoleName' => [
                'required',
                'string',
                'max:128',
                'regex:/^[\pL\pN _-]+$/u',
                Rule::unique('roles', 'name')->where('guard_name', $this->creatingGuardName),
            ],
            'creatingGuardName' => ['required', 'string', 'max:64'],
            'creatingCategory' => ['nullable', 'string', 'max:64'],
            'creatingSortOrder' => ['required', 'integer', 'min:0', 'max:65535'],
            'creatingDescription' => ['nullable', 'string', 'max:2000'],
            'creatingIsAssignable' => ['boolean'],
            'creatingBadgeColor' => [
                'required',
                'string',
                Rule::in(array_keys($iconRegistry->roleUserManagementBadgeColors())),
            ],
            'creatingBadgeVariant' => [
                'required',
                'string',
                Rule::in(array_keys($iconRegistry->roleUserManagementBadgeVariants())),
            ],
            'creatingBadgeIcon' => [
                'required',
                'string',
                Rule::in(array_keys($iconRegistry->roleUserManagementOptions())),
            ],
        ]);

        $roleName = trim($this->creatingRoleName);

        $role = Role::query()->create([
            'name' => $roleName,
            'guard_name' => $this->creatingGuardName,
            'category' => trim($this->creatingCategory) !== '' ? trim($this->creatingCategory) : null,
            'sort_order' => $this->creatingSortOrder,
            'description' => trim($this->creatingDescription) !== '' ? trim($this->creatingDescription) : null,
            'is_system' => false,
            'is_assignable' => $this->creatingIsAssignable,
        ]);

        $roleBadges = $settings->roleBadges;
        $roleBadges[$role->name] = [
            'color' => $this->creatingBadgeColor,
            'variant' => $this->creatingBadgeVariant,
            'icon' => $this->creatingBadgeIcon,
        ];

        $settings->roleBadges = $roleBadges;
        $settings->save();

        $adminActivity->roleCreated(
            role: $role,
            metadata: [
                'category' => $role->category,
                'sort_order' => $role->sort_order,
                'description' => $role->description,
                'is_system' => $role->is_system,
                'is_assignable' => $role->is_assignable,
            ],
            badge: $roleBadges[$role->name] ?? [],
        );

        $this->resetCreateRoleModal();

        Flux::toast(
            // i18n-native: __('admin.roles.messages.role_created.heading')
            heading: __('admin.roles.messages.role_created.heading'),
            // i18n-native: __('admin.roles.messages.role_created.text')
            text: __('admin.roles.messages.role_created.text', [
                'role' => $role->name,
            ]),
            variant: 'success',
            duration: 3000,
        );

        $this->dispatch('$refresh');
    }

public function saveRole(AppDisplaySettings $settings, IconRegistry $iconRegistry, AdminActivity $adminActivity): void
    {
        if ($this->editingRoleId === null) {
            return;
        }

        $this->validate([
            'editingCategory' => ['nullable', 'string', 'max:64'],
            'editingSortOrder' => ['required', 'integer', 'min:0', 'max:65535'],
            'editingDescription' => ['nullable', 'string', 'max:2000'],
            'editingIsAssignable' => ['boolean'],
            'editingBadgeColor' => [
                'required',
                'string',
                Rule::in(array_keys($iconRegistry->roleUserManagementBadgeColors())),
            ],
            'editingBadgeVariant' => [
                'required',
                'string',
                Rule::in(array_keys($iconRegistry->roleUserManagementBadgeVariants())),
            ],
            'editingBadgeIcon' => [
                'required',
                'string',
                Rule::in(array_keys($iconRegistry->roleUserManagementOptions())),
            ],
        ]);

        $role = Role::query()->findOrFail($this->editingRoleId);

        $beforeBadge = $settings->roleBadges[$role->name] ?? [];

        $before = [
            'metadata' => [
                'category' => $role->category,
                'sort_order' => $role->sort_order,
                'description' => $role->description,
                'is_system' => $role->is_system,
                'is_assignable' => $role->is_assignable,
            ],
            'badge' => [
                'color' => $beforeBadge['color'] ?? null,
                'variant' => $beforeBadge['variant'] ?? null,
                'icon' => $beforeBadge['icon'] ?? null,
            ],
        ];

        $role->forceFill([
            'category' => trim($this->editingCategory) !== '' ? trim($this->editingCategory) : null,
            'sort_order' => $this->editingSortOrder,
            'description' => trim($this->editingDescription) !== '' ? trim($this->editingDescription) : null,
            'is_assignable' => $this->editingIsAssignable,
        ])->save();

        $roleBadges = $settings->roleBadges;
        $roleBadges[$role->name] = [
            'color' => $this->editingBadgeColor,
            'variant' => $this->editingBadgeVariant,
            'icon' => $this->editingBadgeIcon,
        ];

        $settings->roleBadges = $roleBadges;
        $settings->save();

        $role->refresh();

        $after = [
            'metadata' => [
                'category' => $role->category,
                'sort_order' => $role->sort_order,
                'description' => $role->description,
                'is_system' => $role->is_system,
                'is_assignable' => $role->is_assignable,
            ],
            'badge' => [
                'color' => $roleBadges[$role->name]['color'] ?? null,
                'variant' => $roleBadges[$role->name]['variant'] ?? null,
                'icon' => $roleBadges[$role->name]['icon'] ?? null,
            ],
        ];

        $adminActivity->roleUpdated(
            role: $role,
            before: $before,
            after: $after,
        );

        $savedRoleName = (string) $role->name;

        $this->resetEditRoleModal();

        Flux::toast(
            // i18n-native: __('admin.roles.messages.role_saved.heading')
            heading: __('admin.roles.messages.role_saved.heading'),
            // i18n-native: __('admin.roles.messages.role_saved.text')
            text: __('admin.roles.messages.role_saved.text', [
                'role' => $savedRoleName,
            ]),
            variant: 'success',
            duration: 3000,
        );

        $this->dispatch('$refresh');
    }

public function render(RoleBadgeResolver $roleBadgeResolver, IconRegistry $iconRegistry)
    {
        $rolesQuery = Role::query()
            ->withCount('users');

        $rolesQuery
            ->when(trim($this->search) !== '', function ($query): void {
                $search = trim($this->search);

                $query->where(function ($query) use ($search): void {
                    $query->where('name', 'ilike', "%{$search}%")
                        ->orWhere('category', 'ilike', "%{$search}%")
                        ->orWhere('description', 'ilike', "%{$search}%");
                });
            })
            ->when($this->categoryFilter !== '', function ($query): void {
                $query->where('category', $this->categoryFilter);
            })
            ->when($this->assignableFilter !== '', function ($query): void {
                $query->where('is_assignable', $this->assignableFilter === 'yes');
            })
            ->when($this->systemFilter !== '', function ($query): void {
                $query->where('is_system', $this->systemFilter === 'yes');
            });

        if ($this->sortField === 'users_count') {
            $rolesQuery
                ->orderBy('users_count', $this->sortDirection)
                ->orderBy('category')
                ->orderBy('sort_order')
                ->orderBy('name');
        } else {
            $rolesQuery
                ->orderBy($this->sortField, $this->sortDirection)
                ->orderBy('category')
                ->orderBy('sort_order')
                ->orderBy('name');
        }

        $roles = $rolesQuery->paginate($this->normalizedPerPage());

        $roleBadges = $roles
            ->getCollection()
            ->mapWithKeys(fn(Role $role): array => [
                $role->name => $roleBadgeResolver->forRole($role->name),
            ])
            ->all();

        $roleCategories = Role::query()
            ->whereNotNull('category')
            ->select('category')
            ->distinct()
            ->orderBy('category')
            ->pluck('category')
            ->all();
        $this->collectRuntimeDynamicOptions($iconRegistry, $roleCategories);

        return view('components.admin.⚡role-list', [
            'roles' => $roles,
            'roleBadges' => $roleBadges,
            'roleBadgeColorOptions' => $iconRegistry->roleUserManagementBadgeColors(),
            'roleBadgeVariantOptions' => $iconRegistry->roleUserManagementBadgeVariants(),
            'roleBadgeIconOptions' => $iconRegistry->roleUserManagementOptions(),
            'roleCategories' => $roleCategories,
        ]);
    }

private function collectRuntimeDynamicOptions(IconRegistry $iconRegistry, array $roleCategories): void
    {
        if (! class_exists(RuntimeDynamicTranslationCollector::class)) {
            return;
        }

        $collector = app(RuntimeDynamicTranslationCollector::class);

        foreach (['modal_create', 'modal_edit'] as $modalScope) {
            $collector->options(
                key: "admin.partials.role_list.{$modalScope}.role_badge_color_options",
                scope: 'role_badge_color_options',
                values: $iconRegistry->roleUserManagementBadgeColors(),
                source: self::class . '::roleBadgeColorOptions',
                origin: 'runtime',
                sourceType: 'runtime_options',
            );

            $collector->options(
                key: "admin.partials.role_list.{$modalScope}.role_badge_variant_options",
                scope: 'role_badge_variant_options',
                values: $iconRegistry->roleUserManagementBadgeVariants(),
                source: self::class . '::roleBadgeVariantOptions',
                origin: 'runtime',
                sourceType: 'runtime_options',
            );

            $collector->options(
                key: "admin.partials.role_list.{$modalScope}.role_badge_icon_options",
                scope: 'role_badge_icon_options',
                values: $iconRegistry->roleUserManagementOptions(),
                source: self::class . '::roleBadgeIconOptions',
                origin: 'runtime',
                sourceType: 'runtime_options',
            );
        }

        $collector->options(
            key: 'admin.partials.role_list.role_categories',
            scope: 'role_categories',
            values: collect($roleCategories)
                ->mapWithKeys(static fn(string $category): array => [
                    $category => str($category)->headline()->toString(),
                ])
                ->all(),
            source: self::class . '::roleCategories',
            origin: 'db',
            sourceType: 'runtime_db_options',
        );
    }

public function render(RoleBadgeResolver $roleBadgeResolver)
    {
        $query = $this->getFilteredUserQuery()
            ->with('roles');

        if ($this->sortField === 'roles.name') {
            $query = $query
                ->leftJoin('model_has_roles', function ($join) {
                    $join->on('users.id', '=', 'model_has_roles.model_id')
                        ->where('model_has_roles.model_type', '=', User::class);
                })
                ->leftJoin('roles', 'model_has_roles.role_id', '=', 'roles.id')
                ->orderBy('roles.name', $this->sortDirection)
                ->select('users.*');
        } else {
            $query = $query->orderBy('users.' . $this->sortField, $this->sortDirection);
        }

        $this->perPage = $this->normalizePerPage($this->perPage);

        $users = $query->paginate($this->perPage);

        $assignableRoleCountsByCategory = Role::query()
            ->where('is_assignable', true)
            ->selectRaw("COALESCE(category, 'other') as category, COUNT(*) as aggregate")
            ->groupByRaw("COALESCE(category, 'other')")
            ->pluck('aggregate', 'category')
            ->map(fn($value): int => (int) $value)
            ->all();

        $assignedUserCountsByRoleCategory = User::query()
            ->join('model_has_roles', 'users.id', '=', 'model_has_roles.model_id', 'inner', false)
            ->where('model_has_roles.model_type', User::class)
            ->join('roles', 'model_has_roles.role_id', '=', 'roles.id', 'inner', false)
            ->selectRaw("COALESCE(roles.category, 'other') as category, COUNT(DISTINCT users.id) as aggregate")
            ->groupByRaw("COALESCE(roles.category, 'other')")
            ->pluck('aggregate', 'category')
            ->map(fn($value): int => (int) $value)
            ->all();

        $assignedUserCountsByRole = Role::query()
            ->leftJoin('model_has_roles', function ($join) {
                $join->on('roles.id', '=', 'model_has_roles.role_id')
                    ->where('model_has_roles.model_type', '=', User::class);
            })
            ->where('roles.is_assignable', true)
            ->selectRaw("
        roles.name,
        COALESCE(roles.category, 'other') as category,
        roles.sort_order,
        COUNT(DISTINCT model_has_roles.model_id) as users_count
    ")
            ->groupBy('roles.id', 'roles.name', 'roles.category', 'roles.sort_order')
            ->orderBy('roles.category')
            ->orderBy('roles.sort_order')
            ->orderBy('roles.name')
            ->get()
            ->groupBy('category')
            ->map(
                fn($roles) => $roles
                    ->map(fn($role): array => [
                        'name' => (string) $role->name,
                        'usersCount' => (int) $role->users_count,
                    ])
                    ->values()
                    ->all()
            )
            ->all();

        $summary = [
            'totalUsers' => User::query()->count('*'),
            'withoutRoleUsers' => User::query()->doesntHave('roles')->count('*'),
            'assignedUsersByRoleCategory' => $assignedUserCountsByRoleCategory,
            'assignableRolesByCategory' => $assignableRoleCountsByCategory,
            'assignedUsersByRole' => $assignedUserCountsByRole,
        ];

        $assignableRoles = Role::query()
            ->where('is_assignable', true)
            ->orderBy('category')
            ->orderBy('sort_order')
            ->orderBy('name')
            ->get([
                'name',
                'category',
                'sort_order',
                'description',
            ]);

        $roles = $assignableRoles
            ->pluck('name')
            ->all();

        $roleGroups = $assignableRoles
            ->groupBy(fn(Role $role): string => (string) ($role->category ?: 'other'))
            ->map(fn($group) => $group->values())
            ->all();

        $this->collectRuntimeDynamicOptions(array_keys($roleGroups));

        $roleBadges = collect($roles)
            ->mapWithKeys(fn(string $role): array => [
                $role => $roleBadgeResolver->forRole($role),
            ])
            ->all();

        return view('components.admin.⚡user-list', [
            'users' => $users,
            'roles' => $roles,
            'roleGroups' => $roleGroups,
            'roleBadges' => $roleBadges,
            'withoutRoleBadge' => $roleBadgeResolver->withoutRole(),
            'summary' => $summary,
        ]);
    }

private function collectRuntimeDynamicOptions(array $roleCategories): void
    {
        if (! class_exists(RuntimeDynamicTranslationCollector::class)) {
            return;
        }

        app(RuntimeDynamicTranslationCollector::class)->options(
            key: 'admin.partials.user_list.modal.str_headline_category',
            scope: 'Str_headline_category',
            values: collect($roleCategories)
                ->mapWithKeys(static fn(string $category): array => [
                    $category => str($category)->headline()->toString(),
                ])
                ->all(),
            source: self::class . '::roleGroups',
            origin: 'db',
            sourceType: 'runtime_db_options',
        );
    }

