    }

public function names(string $category): array
    {
        return array_keys($this->options($category));
    }

public function resolve(string $name, string $category): array
    {
        $name = trim($name);

        if ($name === '') {
            return $this->fallback();
        }

        $icon = Arr::get($this->options($category), $name);

        if (! is_array($icon)) {
            return $this->fallback();
        }

        $view = (string) ($icon['view'] ?? '');

        if ($view === '' || ! View::exists($view)) {
            return $this->fallback();
        }

        return [
            'name' => $name,
            'label' => (string) ($icon['label'] ?? $name),
            'view' => $view,
        ];
    }

private function sortOptionsByLabel(array $items): array
    {
        uasort($items, static function (array $left, array $right): int {
            return strnatcasecmp(
                (string) ($left['label'] ?? ''),
                (string) ($right['label'] ?? ''),
            );
        });

        return $items;
    }

public static function defaultOptions(): array
    {
        return collect(self::defaults())
            ->mapWithKeys(fn(array $type, string $code): array => [$code => $type['label']])
            ->all();
    }

public static function options(): array
    {
        if (! Schema::hasTable('person_document_types')) {
            return self::defaultOptions();
        }

        $options = self::query()
            ->active()
            ->ordered()
            ->pluck('label', 'code')
            ->all();

        return $options !== [] ? $options : self::defaultOptions();
    }

public static function categoryFor(string $code): string
    {
        if (Schema::hasTable('person_document_types')) {
            $category = self::query()
                ->where('code', $code)
                ->value('category');

            if (is_string($category) && in_array($category, PersonDocument::CATEGORIES, true)) {
                return $category;
            }
        }

        return self::defaults()[$code]['category'] ?? PersonDocument::CATEGORY_OTHER;
    }

public static function firstOrCreateFromLabel(string $label): ?self
    {
        $label = trim($label);

        if ($label === '') {
            return null;
        }

        $code = self::codeFromLabel($label);

        if ($code === '') {
            return null;
        }

        return self::query()->updateOrCreate(
            ['code' => $code],
            [
                'label' => $label,
                'category' => self::categoryFor($code),
                'is_active' => true,
            ],
        );
    }
